2. {"type": "restaurant", "properties": {"tags": ["vegetarian", "self_service", "daily_menu"], "outdoor_seating": null, "indoor_seating": true, "name": "Biberon Fine Food", "phone": "+385 99 731 0226", "opening_hours": "Mo-Sa 09:30-18:00; Su off", "addr:housenumber": "1", "addr:street": "Šijanska cesta", "rating": 4.0, "description": "A self-service restaurant in the Konzum shopping center, offering ready-made daily meals with quick service and convenient parking.", "reviews": ["Self-service canteen with already made food. No waiting, parking available. The portions are not large and prices are not that cheap.", "Food is good, prices are fair, except for the drinks, service is just fine, soup should be with more ingredients and denser. But comparing to other places, excelent"], "price": "medium"}}
3. {"type": "fast_food", "properties": {"tags": ["salads", "wok", "desserts", "vegetarian", "vegan", "gluten_free"], "outdoor_seating": null, "indoor_seating": true, "name": "Mini Mini Street Food", "phone": "+385 99 445 6190", "opening_hours": "Mo-Fr 10:00-22:00; Sa-Su off", "addr:housenumber": "12", "addr:street": "Mletačka", "rating": 4.2, "description": "A small street food restaurant in Pula serving freshly prepared daily lunches, colorful healthy plates, homemade pasta, dumplings, salads, desserts, and other casual dishes made with local and organic ingredients.", "reviews": ["So lovely tiny cosy place! Delicious, homemade food! Service excellent! Perfect chick &vegan options! 🤩⭐️", "Excellent food and ambient. Lots of vegetarian options, big size dishes, good price for the given quantity and quality."], "price": "medium"}}
4. {"type": "restaurant", "properties": {"tags": ["pizza", "city_center", "vegetarian"], "outdoor_seating": false, "indoor_seating": true, "name": "Pizza alla Nonna", "phone": "+385 95 764 5920", "opening_hours": "Mo-Su 10:00-22:00", "addr:housenumber": "3", "addr:street": "Istarska", "rating": 4.6, "description": "A casual pizzeria in the city center, popular for pizza by the slice as well as whole pizzas. It is a convenient spot for a quick bite, especially for people looking for simple, affordable pizza in a relaxed setting.", "reviews": ["Found this place during sight seeing tour! Only 5 minutes by foot away from the popular amphi-theater! Outstanding place with delicious housemadePizza! Prices are really reasonsble!!! Friendly stuff too!", "the pizza is huge and delicious! €2 for a massive slice (see picture:)) the staff were friendly. there is some seating inside but not loads, it’s clean and open - a toilet too i think", "By far the best en biggest pizza we ever had. For a fair price (€15 for a big big one) would recommend to anyone💪🏼"], "price": "low"}}
5. {"type": "cafe", "properties": {"tags": ["balkan", "coffee", "beer"], "outdoor_seating": true, "indoor_seating": true, "name": "Caffe Bar Nozi 7", "phone": null, "opening_hours": "Mo-Tu 05:00-23:00; We-Su 05:00-22:00", "addr:housenumber": "9", "addr:street": "Trg I istarske brigade", "rating": 4.0, "description": "A casual café at Pula’s bus station, suitable for a quick coffee, soft drink, beer, or short stop while waiting for transport.", "reviews": ["This coffee is very close to the bus station. It's clean. The service is quick. The prices are very good 👍 It is a very good place to take a coffee when waiting for your bus :)", "Took the shuttle bus from Pula airport to Pula bus station. 30 kuna (£3.30) each. 15 mins. Hour to kill before bus to heaven ( Rovinj) so popped into this lovely cafe with attached bakery opposite. First beer of the holiday. Great place to wait. Also toilet in bus station has a pay turnstile unlike here. Tabke service for drinks; go to bakery for food. Excellent value. 88Kuna / £10 for 2 coffee and 4*0.33l beers."], "price": "low"}}
6. {"type": "fast_food", "properties": {"tags": ["burgers", "sandwiches", "salads", "vegetarian", "city_center"], "outdoor_seating": false, "indoor_seating": true, "name": "Green", "phone": "+385 52 356 444", "opening_hours": "Mo-Fr 10:00-22:00; Su 14:00-22:00", "addr:housenumber": "4", "addr:street": "Scalierova", "rating": 4.2, "description": "A casual fast-food spot in Pula’s city center, known for burgers, toast sandwiches, tortillas, salads, and quick meals.", "reviews": ["Great service. We had a Fried Chicken Wrap which was very delicious and perfectly rolled. Even spread filling from top to bottom. Perfect place for a fast snack to go.", "We ordered a falafel and chicken wrap. Both super good quality and value for money. Also the toast were large, can easily share one for 2 kids.", "Perfect food whatever you take, for the price and quality is far ahead best place to eat in Pula. Went to few restaurants but Green is far ahead comparing quality, amount you get and prices. Nothing but best for Green.👏🏼"], "price": "medium"}}
7. {"type": "fast_food", "properties": {"tags": ["burgers", "sandwiches", "fries", "salads", "city_center"], "outdoor_seating": false, "indoor_seating": true, "name": "Tanja 3", "phone": "+385 52 210 333", "opening_hours": "Mo-Sa 09:00-24:00; Su 10:00-24:00", "addr:housenumber": "5", "addr:street": "Dubrovačke bratovštine", "rating": 3.8, "description": "A classic city-center fast-food spot in Pula, popular for late-night burgers, fries, and quick comfort food.", "reviews": ["Wow. Small local place always have such a nice food. Two ladies inside. Very polite. Food was amazing. And cheep. Lot of people is coming and eating there. Local hit"], "price": "medium"}}
8. {"type": "fast_food", "properties": {"tags": ["burgers", "sandwiches", "salads", "seafood", "vegetarian", "desserts", "pancakes"], "outdoor_seating": true, "indoor_seating": true, "name": "Sandwich Club", "phone": "+385 52 386 182", "opening_hours": "Mo-Sa 09:00-22:00; Su off", "addr:housenumber": "4", "addr:street": "Sisplac", "rating": 4.6, "description": "A casual fast-food diner in Pula, offering fresh snacks and meals, outdoor seating, vegan and vegetarian options, and a kids’ corner.", "reviews": ["Good fast food with burger options, sandwiches and unique dishes. Friendly staff, fast service. Tables also outside and takeaway. Good value for money.", "I had a wonderful experience at this restaurant. The dishes were delicious and reasonably priced. The staff was very friendly and attentive. I will definitely be coming back!", "Stopped in at Sandwich Club 🥪 yesterday before heading to Aquarium Pula. The food was excellent (try the Cubanito, they have nice Coffee too ☕), the service fantastic (staff were very friendly & good company) & the atmosphere was great (the Spotify playlist having been expertly selected by the team). Couldn't find fault with this place at all - great value for a very reasonable price."], "price": null}}
9. {"type": "restaurant", "properties": {"tags": ["croatian", "local", "seafood", "grill"], "outdoor_seating": true, "indoor_seating": true, "name": "Bistro Cementara", "phone": "+385 99 835 2503", "opening_hours": "Mo-Sa 09:00-17:00; Su off", "addr:housenumber": "4", "addr:street": "Revelanteova", "rating": 4.5, "description": "A casual local bistro, offering affordable daily lunch menus, homemade dishes, seafood and meat specialties, and relaxed dining.", "reviews": ["Very good food and very affordable! It feels very local but there isn't a lot to see around so go there if you're on a walk. Also the waitress was very helpful and cute. 10/10 would go again", "Our accommodation was nearby, so we ended up here by chance. The tomato salad, rump steak with pepper sauce and fries (€13), and the tagliatelle with truffles (€15) were all excellent and very tasty. The prices are absolutely unbeatable. The staff is super friendly. You sit on a small terrace overlooking a parking lot. That's the only downside. Otherwise, a definite thumbs up for authentic, delicious Croatian cuisine.", "A hidden gem in the Docklands. Simple, but the food is fantastic and beautifully presented. We had grilled fish, calamari, and truffle pasta. The service was also very friendly (only Croatian spoken)."], "price": "low"}}
10. {"type": "restaurant", "properties": {"tags": ["international", "meat", "fries", "seafood", "pasta", "grill", "desserts"], "outdoor_seating": null, "indoor_seating": true, "name": "Restoran lesnina XXXL", "phone": "385 52 579 980", "opening_hours": "Mo-Sa 09:00-19:30; Su off", "addr:housenumber": "60", "addr:street": "Šijanska cesta", "rating": null, "description": "A casual self-service shopping restaurant in Lesnina offering hearty everyday meals like schnitzels, burgers, grilled dishes, salads, pasta, fish and simple desserts at accessible prices.", "reviews": null, "price": "medium"}}

