6. {"type": "artwork", "properties": {"name": "James Joyce", "tags": ["artwork", "statue", "historic", "city_center", "landmark", "near_attractions"], "description": "Bronze statue of James Joyce in central Pula near the Arch of the Sergii, commemorating the famous Irish writer’s stay in the city and its place in his early literary life.", "rating": 4.7, "reviews": ["This statue made we search more about this Irish novelist. He was an important writer whose books are read today. Here you can take selfies with the statue and enjoy a cup of coffee in a table next to the statue.", "Nice sculpture. Beside a restaurant. If not known, or checked carefully, one can miss it for a person waiting outside a restaurant.", "Nice statue. You can sit with him."]}}
7. {"type": "artwork", "properties": {"name": "Mate Parlov", "tags": ["sculpture", "statue", "monument", "city_center", "near_attractions"], "description": "A public sculpture dedicated to one of Pula’s most celebrated athletes and a legendary figure in Croatian boxing. Located on Giardini, it honors his lasting connection to the city and keeps the memory of his sporting legacy alive in the heart of Pula.", "rating": 4.8, "reviews": ["The appearance of the statue doesn't give away that it's a boxer. Too bad.", "A nice gesture and thanks from the city of Pula and its citizens"]}}
8. {"type": "artwork", "properties": {"name": "Žena s mijehom", "tags": ["artwork", "sculpture", "island", "national_park", "monument"], "description": "Žena s mijehom is a bronze sculpture by Frane Kršinić, created in 1956 and located in Brijuni National Park as part of the Živa voda memorial site. The sculpture depicts a woman bending forward and pouring water from a goatskin bag into a stone basin below, symbolizing the importance of fresh water on the island. It is both an artistic landmark and a memorial to the technical achievement of discovering and drawing underground spring water on Brijuni.", "rating": null, "reviews": null}}
9. {"type": "park", "properties": {"name": "Park Mladenaca", "tags": ["park", "city_center", "family_friendly", "memorial", "near_attractions"], "description": "Small central park in Pula near the Forum, known for its landscaped greenery, evening atmosphere, and popularity for wedding photos and sunset walks.", "rating": 5.0, "reviews": ["A great place to watch sunset.", "A small park next to the ancient temple.", "A small green space near the central Roman Forum and the Temple of Augustus. It's certainly not the best place for jogging or long walks, but it's very well-kept, both for its lawn and trees, and boasts a curious monument located within. It's certainly a great place for a relaxing break in the shade, surrounded by stunning monuments."]}}
10. {"type": "artwork", "properties": {"name": "Marko Marulić", "tags": ["statue", "sculpture", "monument", "park", "artwork", "city_center"], "description": "A bronze public sculpture dedicated to one of the most important figures of Croatian literature, placed in a small park near the waterfront and the railway station. Its calm, dignified form reflects the intellectual and cultural legacy of the Renaissance writer, adding a literary and commemorative note to the surrounding urban landscape.", "rating": 4.0, "reviews": null}}
